// A country as a source names it (a code, or a name in English) → its alpha-2 code, or null.
export function countryCode(v) {
  const s = String(v ?? '').trim();
  if (/^[A-Za-z]{2}$/.test(s) && names[s.toUpperCase()]) return s.toUpperCase();
  const key = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, ' ').trim();
  return aliases[key] ?? null;
}
